let UP_MUL = 1; // 히어로(대장장이 두루미)의 강화 비용 배율. newGame 이 설정
function upgradeCost(bought) { const c = CONST.UP_COST0 + CONST.UP_COSTK * bought; return UP_MUL === 1 ? c : Math.round(c * UP_MUL); }
