  CONST.ROUNDS = R.rounds || CONST.ROUNDS_BASE;
  const seed = forceSeed || Math.floor(Math.random() * 2147483646) + 1; // 매 판 새 시드 (랭킹 판도 서버가 이 시드로 재현 검증)
  const rng = makeRngs(seed);
  const hero = heroOfDay(rng.hero, R.heroPool);
